contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 credChainId_, uint256 credId_, string calldata verificationType_, address protocolFeeDestination_) public {
        bool reverted;
        try c.initialize(credChainId_, credId_, verificationType_, protocolFeeDestination_) {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool ok = !reverted && c.credChainId() == credChainId_ && c.credId() == credId_
            && keccak256(bytes(c.verificationType())) == keccak256(bytes(verificationType_));

        bool revertedAgain;
        try c.initialize(credChainId_, credId_, verificationType_, protocolFeeDestination_) {
            revertedAgain = false;
        } catch {
            revertedAgain = true;
        }

        assert(ok && revertedAgain);
    }
}

