contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 artId_, uint256 quantity_, uint256 transferQuantity_, address from_, address to_) public payable {
        require(to_ != address(0));
        require(quantity_ > 0);
        require(transferQuantity_ > 0 && transferQuantity_ <= quantity_);

        c.claimFromFactory{value: 0}(artId_, from_, from_, from_, quantity_, bytes32(0), "");

        uint256 tokenId = c.getTokenIdFromFactoryArtId(artId_);

        uint256 balFromBefore = c.balanceOf(from_, tokenId);
        uint256 balToBefore = c.balanceOf(to_, tokenId);

        bool reverted;
        try c.safeTransferFrom(from_, to_, tokenId, transferQuantity_, "") {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balFromAfter = c.balanceOf(from_, tokenId);
        uint256 balToAfter = c.balanceOf(to_, tokenId);

        assert(
            reverted
                ? (balFromAfter == balFromBefore && balToAfter == balToBefore)
                : (balFromAfter == balFromBefore - transferQuantity_ && balToAfter == balToBefore + transferQuantity_)
        );
    }
}

