        bool reverted;
        try c.safeTransferFrom(address(this), to_, tokenId, transferQuantity_, "") {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balanceAfter = c.balanceOf(address(this), tokenId);
        uint256 toBalanceAfter = c.balanceOf(to_, tokenId);

        assert(
            reverted
                ? (balanceAfter == balanceBefore && toBalanceAfter == 0)
                : (balanceAfter == balanceBefore - transferQuantity_ && toBalanceAfter == transferQuantity_)
        );
    }

    receive() external payable {}
}

