contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 artId, uint256 fee) public payable {
        require(address(this).balance >= fee, "not enough balance");

        uint256 beforeCounter = c.tokenIdCounter();

        uint256 createdTokenId;
        bool reverted;
        try c.createArtFromFactory{value: fee}(artId) returns (uint256 t) {
            createdTokenId = t;
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 afterCounter = c.tokenIdCounter();
        uint256 boundTokenId = c.getTokenIdFromFactoryArtId(artId);

        assert(
            reverted
                ? afterCounter == beforeCounter
                : (boundTokenId == createdTokenId && afterCounter == beforeCounter + 1)
        );
    }

    receive() external payable {}
}
